core::DocumentState Source(){core::Image image;if(!image.Create(500,360))throw std::runtime_error("Composition fixture allocation");auto state=core::Document(image).State();for(int i=0;i<3;++i){core::Annotation a;a.tool=core::Tool::Rectangle;a.rect={30+i*120,30,110+i*120,100};a.text=L"keep";a.color=RGB(230,20,20);state.objects.push_back(a);}return state;}
uint32_t Crc(const std::vector<BYTE>& data){uint32_t value=~0u;for(size_t i=0;i<data.size()-4;++i){value^=data[i];for(int bit=0;bit<8;++bit)value=(value>>1)^(0xEDB88320u&static_cast<uint32_t>(-static_cast<int>(value&1)));}return ~value;}
void Seal(std::vector<BYTE>& data){auto crc=Crc(data);memcpy(data.data()+data.size()-4,&crc,4);}
std::vector<BYTE> Legacy(int version){std::vector<BYTE> bytes;auto raw=[&](const void* p,size_t n){const auto* b=static_cast<const BYTE*>(p);bytes.insert(bytes.end(),b,b+n);};auto integer=[&](int32_t n){raw(&n,4);};auto str=[&](const wchar_t* text){integer(static_cast<int>(wcslen(text)));raw(text,wcslen(text)*2);};raw("SCTPROJ\0",8);integer(version);std::vector<BYTE> png;CString error;core::Image base;base.Create(2,2);if(!services::EncodeImage(base,L"png",100,png,error))throw std::runtime_error("Legacy fixture encode");integer(static_cast<int>(png.size()));raw(png.data(),png.size());integer(1);integer(static_cast<int>(core::Tool::Rectangle));RECT rect{0,0,2,2};raw(&rect,sizeof(rect));integer(0);str(L"old");str(L"Arial");for(int n:{255,0,0,3,28,90,1,2})integer(n);integer(0);if(version>=2){POINT focus{};raw(&focus,sizeof(focus));}integer(0);if(version>=3)for(int n:{0,0,0,255})integer(n);if(version>=4)integer(0);if(version>=5)integer(0);integer(0);Seal(bytes);return bytes;}
