    auto grouped=Group(source,{0,1});check(grouped.objects[0].group&&grouped.objects[0].group==grouped.objects[1].group&&grouped.objects[2].group==0&&grouped.base==source.base&&grouped.objects[0].text==source.objects[0].text,"group metadata preserves base/content/layer order without flattening");check(Expand(grouped,{1})==Indices({0,1}),"clicking one group member expands to every member");doc.Commit(grouped);check(doc.Undo()&&doc.State().objects[0].group==0&&doc.Redo()&&doc.State().objects[1].group!=0,"group and ungroup metadata participate in bounded Undo/Redo");
    auto box=Bounds(grouped,{0});RECT moved=box;OffsetRect(&moved,20,35);auto translated=Transform(grouped,{0},moved,false);check(translated.objects[0].rect.left==50&&translated.objects[1].rect.left==170&&translated.objects[2].rect.left==270,"group translate preserves relative member positions and untouched siblings");RECT doubled{box.left,box.top,box.left+(box.right-box.left)*2,box.top+(box.bottom-box.top)*2};auto scaled=Transform(grouped,{0},doubled,true);check(scaled.objects[1].rect.left==270&&scaled.objects[0].rect.right==190&&scaled.objects[0].width==6&&scaled.objects[0].fontSize==56,"group scaling maps member geometry and bounded pen/font sizes together");
    auto color=Recolor(grouped,{1},RGB(4,5,6));check(color.objects[0].color==RGB(4,5,6)&&color.objects[1].color==RGB(4,5,6)&&color.objects[2].color==source.objects[2].color,"group recolor affects all and only expanded selected objects");auto locked=Lock(grouped,{0},true);for(auto action:{0,1,2,3}){bool rejected=false;try{if(action==0)Remove(locked,{0});else if(action==1)Recolor(locked,{0},0);else if(action==2)Transform(locked,{0},moved,false);else Group(locked,{0},true);}catch(const std::exception&){rejected=true;}check(rejected,"locked group rejects mutation before any state is changed");}check(!Locked(Lock(locked,{1},false),{0}),"unlocking a member unlocks the complete group");
    Indices ids;auto duplicated=Duplicate(grouped,{0},ids);check(ids==Indices({3,4})&&duplicated.objects[3].group==duplicated.objects[4].group&&duplicated.objects[3].group!=grouped.objects[0].group,"duplicate remaps group identity and returns only the added selection");auto pasted=grouped;Append(pasted,locked.objects);check(pasted.objects[3].group!=grouped.objects[0].group&&pasted.objects[3].group==pasted.objects[4].group&&pasted.objects[3].locked&&pasted.objects[0].rect.left==30,"cross-document append remaps colliding groups without altering destination or lock state");
    check(Remove(grouped,{1}).objects.size()==1&&Group(grouped,{0},true).objects[1].group==0,"remove and ungroup expand the full group atomically");auto layered=Reorder(grouped,{0},1,ids);check(ids==Indices({1,2})&&layered.objects[0].group==0&&layered.objects[1].group==layered.objects[2].group,"group layer change preserves relative member order and selection indices");
